sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // Copy attachments from Idea to story/epic/demand
    var attachmentGR = new GlideRecord('sys_attachment');
    attachmentGR.addQuery('table_name', 'idea');
    attachmentGR.addQuery('table_sys_id', current.sys_id);
    attachmentGR.query();
    while (attachmentGR.next()) {
        var targetTable;
        if (current.task.number.indexOf("STRY") > -1) {
            targetTable = 'rm_story';
        } else if (current.task.number.indexOf("DEM") > -1) {
            targetTable = 'dmn_demand';
        } else if (current.task.number.indexOf("EPIC") > -1) {
            targetTable = 'rm_epic';
        } else {
            continue; // Skip if task number doesn't match any of the specified prefixes
        }

        // Check if the attachment already exists in the target record
        var targetAttachmentGR = new GlideRecord('sys_attachment');
        targetAttachmentGR.addQuery('table_name', targetTable);
        targetAttachmentGR.addQuery('table_sys_id', current.task.sys_id);
        targetAttachmentGR.addQuery('file_name', attachmentGR.file_name);
        targetAttachmentGR.query();
        if (!targetAttachmentGR.hasNext()) {
            // If no attachment with the same file name exists in the target record, copy it
            GlideSysAttachment.copy('idea', current.sys_id, targetTable, current.task.sys_id);
        }
    }
})(current, previous);
